using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class Incident:Entity<Guid>{private Incident(){}private Incident(Guid id,Guid tenantId,Guid electionId,Guid? electionCenterId,Guid reporterId,Guid? assignedToId,short stateId,short severityId,string title,string description,bool confidential){if(tenantId==Guid.Empty||electionId==Guid.Empty||reporterId==Guid.Empty)throw new ArgumentException("Incident references are required.");if(stateId<=0||severityId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));Id=id;TenantId=tenantId;ElectionId=electionId;ElectionCenterId=electionCenterId;ReporterUserId=reporterId;AssignedToUserId=assignedToId;StateId=stateId;SeverityId=severityId;Title=OperationRules.Text(title,200);Description=OperationRules.Text(description,4000);IsConfidential=confidential;ReportedAtUtc=DateTimeOffset.UtcNow;Version=1;}public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public Guid? ElectionCenterId{get;private set;}public Guid ReporterUserId{get;private set;}public Guid? AssignedToUserId{get;private set;}public short StateId{get;private set;}public short SeverityId{get;private set;}public string Title{get;private set;}=string.Empty;public string Description{get;private set;}=string.Empty;public bool IsConfidential{get;private set;}public DateTimeOffset ReportedAtUtc{get;private set;}public int Version{get;private set;}public static Incident Report(Guid tenantId,Guid electionId,Guid? centerId,Guid reporterId,Guid? assigneeId,short stateId,short severityId,string title,string description,bool confidential=false)=>new(Guid.NewGuid(),tenantId,electionId,centerId,reporterId,assigneeId,stateId,severityId,title,description,confidential);public void MoveTo(short stateId){if(stateId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));StateId=stateId;Version++;}}
